import{z as B,x as A,o as e,c as p,q as E,j as l,D as n,d as t,s,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"低 n 吸收体","description":"","frontmatter":{"title":"低 n 吸收体","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/low-n-absorber.md","filePath":"litho/low-n-absorber.md","lastUpdated":1791063341000}'),d={name:"litho/low-n-absorber.md"};function h(D,a,m,k,c,b){const r=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=E('<h1 id="低-n-吸收体" tabindex="-1">低 n 吸收体 <a class="header-anchor" href="#低-n-吸收体" aria-label="Permalink to &quot;低 n 吸收体&quot;">​</a></h1><div class="epigraph"><p>吸收体的 n 若贴近真空，厚度带来的相移和三维电磁变弱。减薄不再只靠加 k，也可以靠把折射率拉回 1。</p><footer>—— 对照 Philipsen、van Setten、imec 对 low-n EUV 吸收体的公开讨论</footer></div><p><a href="/litho/reticle-backside-particles">上一课</a>收束掩模台背面。缺口转到版正面：挡住多层反射的那一层，其复折射率 \\((n,k)\\) 决定阴影、相位和最佳焦点。<a href="/litho/euv-absorber-materials">吸收体材料</a> 已把 TaBN 与高 k（如 Ni）路线分开；本课专攻低 n——让 \\(n\\to 1\\)，三维相位税下降。相移掩模作为主动利用相位的另一条路，留给<a href="/litho/euv-phase-shift-mask">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钽基吸收体要足够厚才压住 13.5 nm，厚度 × CRA 给出几何阴影，n 偏离 1 又给出额外相移，空中像的最佳焦点随节距走。高 k 路线用更薄的膜换同样光学密度，阴影缩短，但刻蚀与缺陷链要重建。低 n 路线从相位端动手：即使厚度暂不能减到 Ni 那么薄，只要 n 接近真空，掩模作为相位物的权重下降，HV 偏置和焦面分裂减轻。</p><p>缺口是把 n 从材料表里单独提出来，而不是再列一次谁在量产。High-NA 角更大，同样的 n–厚度乘积更不可接受。</p><p><span class="marginnote">数字实例：几何阴影约等于厚度乘视角的正切——若 CRA=6°，吸收体每厚 10 nm 就多约 1 nm 水平阴影；膜从 60 nm 减到 30 nm，阴影直接砍半。High-NA 角更大，同样的厚度税更重，这就是低 n 在 High-NA 更急的原因。</span></p><p><span class="marginnote">低 n 和高 k 不是互斥口号。理想吸收体是高 k 且 n≈1 且可刻、可检。公开讨论里往往只能先抓住一维。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光学筛选：在 13.5 nm 查材料的 \\(n+ik\\)，目标 k 够大以减薄，n 靠近 1 以减相移。候选在会议文献中包括某些氮化物、合金和多层吸收体，资格以掩模厂能否沉积、干法出侧壁、在 DUV/电子束下有检测衬度为准。OPC 的 M3D 库必须用新 n、k 重校准；把 TaBN 的紧凑模型改个名字会系统性偏。</p><p>与变形倍率一起看：掩模侧角度被压回多层窗之后，剩余 CRA 仍要吸收体配合。低 n 是给剩余角的相位余量。</p><h3 id="检测衬度是材料资格的第三轴" tabindex="-1">检测衬度是材料资格的第三轴 <a class="header-anchor" href="#检测衬度是材料资格的第三轴" aria-label="Permalink to &quot;检测衬度是材料资格的第三轴&quot;">​</a></h3><p>n、k 好看但在 DUV 检验或电子束下看不见，缺陷会漏到光化甚至硅片。低 n 材料往往衬度也低。掩模厂工具链接不住，光学优势落不到量产。材料表至少三列：13.5 nm 的 n/k、刻蚀选择比、检验衬度。缺一列就还是实验室膜。</p>',13)),(e(),l(o,null,{default:n(()=>[s(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TA%5B%22TaBN%3A%20%E6%88%90%E7%86%9F%E5%81%8F%E5%8E%9A%22%5D%20--%3E%20SH%5B%22%E9%98%B4%E5%BD%B1%20%2B%20%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20HK%5B%22%E9%AB%98%20k%20%E5%87%8F%E8%96%84%22%5D%20--%3E%20SH2%5B%22%E9%98%B4%E5%BD%B1%E9%99%8D%22%5D%0A%20%20LN%5B%22%E4%BD%8E%20n%20%E8%BF%91%201%22%5D%20--%3E%20PH%5B%22%E7%9B%B8%E7%A7%BB%E9%99%8D%22%5D%0A%20%20SH%20--%3E%20BF%5B%22%E6%9C%80%E4%BD%B3%E7%84%A6%E7%82%B9%E5%88%86%E8%A3%82%22%5D%0A%20%20PH%20--%3E%20BF%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"Kirchhoff 薄屏假设吸收体只有透过率 0/1。实际电磁里，膜内光程 \\((n-1)t\\) 和吸收 \\(kt\\) 一起改复振幅，侧壁导波和顶部倒角再叠加。n→1 时，厚度主要当吸收长度用，相位物体变弱，通过焦点的 CD 曲线更接近「纯振幅掩模」。Finders、van Setten、Philipsen 等把焦面偏移和 PV-band 对吸收体光学常数的灵敏度写成 M3D 的核心图像。",-1)),(e(),l(o,null,{default:n(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E5%8E%9A%E5%BA%A6%20t%22%5D%20--%3E%20P%5B%22%E5%85%89%E7%A8%8B%20(n-1)t%3A%20%E5%AE%9A%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20N%5B%22n%20%E8%B6%8B%E8%BF%91%201%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20TAX%5B%22%E7%9B%B8%E4%BD%8D%E7%A8%8E%3A%20%E7%84%A6%E9%9D%A2%E5%88%86%E8%A3%82%20%2F%20HV%20%E5%81%8F%E7%BD%AE%22%5D%0A%20%20N%20--%3E%20WEAK%5B%22%E7%9B%B8%E4%BD%8D%E7%89%A9%E4%BD%93%E5%8F%98%E5%BC%B1%22%5D%0A%20%20K%5B%22k%3A%20%E5%90%B8%E6%94%B6%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20THIN%5B%22k%20%E5%A4%A7%20%E2%86%92%20t%20%E5%8F%AF%E8%96%84%20%E2%86%92%20%E9%98%B4%E5%BD%B1%E7%9F%AD%22%5D%0A%20%20WEAK%20--%3E%20AMP%5B%22%E5%83%8F%E6%9B%B4%E6%8E%A5%E8%BF%91%E7%BA%AF%E6%8C%AF%E5%B9%85%E6%8E%A9%E6%A8%A1%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">这张图把材料表拆成两条独立的轴：\\(n\\) 沿「相位」轴起作用，\\(k\\) 沿「厚度/阴影」轴起作用。低 n 与高 k 是两个不同的旋钮，理想吸收体是两个都拧到位，还能刻、能检。</span></p><p><span class="marginnote">直觉类比：\\(n\\) 是光在介质里「拖堂」的程度。真空不拖堂（\\(n=1\\)）；吸收体 \\(n\\) 偏离 1 越多，走膜内那部分光被拖得越久，与没走膜的光产生相位差——焦点就跟着漂。低 n 就是把「拖堂」调成和真空一样。</span></p><p><span class="marginnote">不要把某张实验室低 n 膜的 n、k 写成量产规格。本课钉机制：n 管相位，k 管能薄多少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把相移掩模的 180° 槽写完，下一课才主动用相位。不重写掩模厂钽刻蚀食谱。n、k 表换了，紧凑 M3D 库整库作废，不能只改 OPC 偏置常数。出处：Philipsen / imec low-n absorber；van Setten、Finders M3D；吸收体材料课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低 n 减轻吸收体作为相位物的权重，从而减轻焦面分裂与部分 3D 偏置。</li><li>与高 k 减薄是同一张材料预算的两个轴。</li><li>下一课：若相位不可避免，能否把它做成相移掩模。</li><li>出处：Philipsen、van Setten、Finders；imec / SPIE 公开讨论。</li></ul>',7))])}const P=B(d,[["render",h]]);export{u as __pageData,P as default};
